def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_last, opp_last = history[-1]
    if opp_last == 'D' and my_last == 'C':
        return 'D'
    if opp_last == 'D' and my_last == 'D':
        return 'C'
    if n >= 2:
        my_prev, opp_prev = history[-2]
        if opp_prev == 'D' and opp_last == 'C':
            return 'D'
        if opp_prev == 'C' and opp_last == 'D':
            return 'D'
    if n > 0 and history[-1][1] == 'C':
        if n % 7 == 0:
            return 'D'
    return 'C'
